const body = $input.first().json.body;

// Parse callback data
const callbackData = body.callback_query?.data || '';
const chatId = body.callback_query?.from?.id;
const callbackQueryId = body.callback_query?.id;

if (!callbackData || !chatId || !callbackQueryId) {
  return [{ json: { error: 'Invalid callback data' } }];
}

// Format: "pick:{prescriptionId}:{pharmacyId}"
const parts = callbackData.split(':');
if (parts[0] !== 'pick' || parts.length < 3) {
  return [{ json: { error: 'Invalid callback format: ' + callbackData } }];
}

const prescriptionId = parseInt(parts[1]);
const pharmacyId = parseInt(parts[2]);
const token = "8644047281:AAHywXMMM9zpDThyBj_FOgme46RZi_GhzRk";

// Fetch pharmacy name
let pharmacyName = 'Pharmacie #' + pharmacyId;
try {
  const pharmacies = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://localhost:8081/api/pharmacies',
    headers: { 'Content-Type': 'application/json' }
  });
  const pharmacy = (Array.isArray(pharmacies) ? pharmacies : []).find(p => p.id === pharmacyId);
  if (pharmacy) pharmacyName = pharmacy.pharmacyName;
} catch(e) {}

// Assign pharmacy via backend
try {
  await this.helpers.httpRequest({
    method: 'PUT',
    url: 'http://localhost:8765/api/prescriptions/' + prescriptionId + '/assign-pharmacy',
    headers: { 'Content-Type': 'application/json' },
    body: { pharmacyId: pharmacyId }
  });
} catch(e) {
  // Continue even if backend fails - still answer callback
}

// Answer callback query
await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.telegram.org/bot' + token + '/answerCallbackQuery',
  headers: { 'Content-Type': 'application/json' },
  body: {
    callback_query_id: callbackQueryId,
    text: '\u2705 Pharmacie s\u00E9lectionn\u00E9e !'
  }
});

// Send confirmation to patient
const confirmText = '\u2705 *' + pharmacyName + '* s\u00E9lectionn\u00E9e pour l\'ordonnance #' + prescriptionId + '.\n\nVous serez notifi\u00E9 d\u00E8s que l\'ordonnance sera pr\u00EAte.';

await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.telegram.org/bot' + token + '/sendMessage',
  headers: { 'Content-Type': 'application/json' },
  body: {
    chat_id: chatId,
    text: confirmText,
    parse_mode: 'Markdown'
  }
});

return [{ json: { success: true, prescriptionId, pharmacyId, pharmacyName } }];
